DROP TABLE IF EXISTS `expense_driver_attendance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `expense_driver_attendance` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `record_date` date NOT NULL COMMENT '日期',
  `person_name` varchar(50) NOT NULL COMMENT '填写人',
  `requirement_code` varchar(100) DEFAULT NULL COMMENT '试验需求编号',
  `expense_settle_project` varchar(200) DEFAULT NULL COMMENT '垫付费用结算项目',
  `test_version` varchar(100) DEFAULT NULL COMMENT '试验版本',
  `test_task` varchar(50) DEFAULT NULL COMMENT '试验任务',
  `car_number` varchar(200) DEFAULT NULL COMMENT '车辆编号',
  `start_time` time(6) DEFAULT NULL COMMENT '上班时间',
  `end_time` time(6) DEFAULT NULL COMMENT '下班时间',
  `is_overtime` varchar(10) NOT NULL DEFAULT '否' COMMENT '当前是否加班',
  `work_duration` decimal(4,1) NOT NULL DEFAULT '0.0' COMMENT '当天工作日时长(h)',
  `overtime_hours` decimal(4,1) NOT NULL DEFAULT '0.0' COMMENT '当前加班时长(h)',
  `total_hours` decimal(4,1) NOT NULL DEFAULT '0.0' COMMENT '当天总工时',
  `travel_status` varchar(50) DEFAULT NULL COMMENT '出差状态',
  `work_location` varchar(200) DEFAULT NULL COMMENT '工作地点',
  `location_coords` varchar(100) DEFAULT NULL COMMENT '定位位置',
  `vehicle_initial_mileage` decimal(8,1) DEFAULT NULL COMMENT '车辆初始里程',
  `vehicle_end_mileage` decimal(8,1) DEFAULT NULL COMMENT '车辆结束里程',
  `vehicle_test_mileage` decimal(8,1) DEFAULT NULL COMMENT '车辆测试里程',
  `daily_advance_total` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '当日垫付费用总计',
  `expense_details` json DEFAULT NULL COMMENT '费用明细: [{"type":"过路费","amount":0,"attachment":""},...]',
  `approver1` varchar(50) DEFAULT NULL COMMENT '审批人1',
  `approver1_result` varchar(20) DEFAULT NULL COMMENT '审批人1审核结果',
  `approver2` varchar(50) DEFAULT NULL COMMENT '审批人2',
  `approver2_result` varchar(20) DEFAULT NULL COMMENT '审核结果',
  `attachment_url` varchar(500) DEFAULT NULL COMMENT '考勤打卡附件',
  `expense_attachment_url` varchar(500) DEFAULT NULL COMMENT '垫付费用附件',
  `project_id` bigint NOT NULL COMMENT '所在车型项目',
  `test_order_id` bigint DEFAULT NULL COMMENT '试验单号',
  PRIMARY KEY (`id`),
  KEY `fk_expense__expense__d28e2416` (`project_id`),
  KEY `fk_expense__expense__c38b093e` (`test_order_id`),
  KEY `idx_expense_dri_created_f84716` (`created_at`),
  KEY `idx_expense_dri_updated_a9cdc2` (`updated_at`),
  KEY `idx_expense_dri_record__edebd2` (`record_date`),
  CONSTRAINT `fk_expense__expense__c38b093e` FOREIGN KEY (`test_order_id`) REFERENCES `expense_test_order` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_expense__expense__d28e2416` FOREIGN KEY (`project_id`) REFERENCES `expense_project` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8694 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='驾驶员考勤打卡';
